<template>
  <section class="admin-page"><div class="admin-inner"><p class="eyebrow">ADMIN / HARI SANTRI 2026</p><h1>Reward voucher & settlement</h1><p class="intro">Voucher diterbitkan selektif oleh admin. Settlement baru mengurangi saldo tenant setelah pembayaran nyata dikonfirmasi.</p><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="success" class="success" role="status">{{ success }}</p><div class="panel"><h2>Terbitkan voucher reward</h2><div class="form-grid"><label>Pilih peserta berbayar tanpa voucher<select v-model="createForm.participantId"><option value="">Pilih peserta</option><option v-for="participant in participants" :key="participant.participant_id" :value="participant.participant_id">{{ participant.participant_name }} · {{ participant.activity_type }}</option></select></label><label>Saldo awal (IDR)<input v-model.number="createForm.initialBalance" type="number" min="0"></label></div><button class="button primary" :disabled="busy || !createForm.participantId" @click="createVoucher">Terbitkan voucher</button></div><div class="panel"><h2>Penyesuaian saldo</h2><div class="form-grid"><label>Pilih voucher<select v-model="adjustForm.id"><option value="">Pilih voucher</option><option v-for="row in vouchers" :key="row.voucher_id" :value="row.voucher_id">{{ row.participant_name }} · {{ money(row.balance) }}</option></select></label><label>Perubahan (+/-)<input v-model.number="adjustForm.amount" type="number"></label><label class="wide">Alasan<input v-model.trim="adjustForm.reason"></label></div><button class="button primary" :disabled="busy" @click="adjustVoucher">Simpan penyesuaian</button></div><div class="panel"><div class="heading"><h2>Daftar voucher</h2><button class="button secondary" @click="load">Muat ulang</button></div><div class="table-wrap"><table><thead><tr><th>Peserta</th><th>Saldo</th><th>Berlaku</th><th>Status</th><th>Aksi</th></tr></thead><tbody><tr v-for="row in vouchers" :key="row.voucher_id"><td>{{ row.participant_name }}</td><td>{{ money(row.balance) }}</td><td>{{ formatDate(row.expires_at) }}</td><td>{{ row.status }}</td><td><button class="link-button" :disabled="row.balance !== 0 || row.status !== 'active'" @click="revoke(row.voucher_id)">Nonaktifkan</button></td></tr></tbody></table></div></div><div class="panel"><div class="heading"><h2>Laporan settlement exhibitor</h2><button class="button secondary" @click="load">Muat ulang</button></div><p>Admin hanya memantau laporan. Pengajuan dan konfirmasi pembayaran dilakukan oleh pemilik tenant.</p><div class="table-wrap"><table><thead><tr><th>Exhibitor</th><th>Nominal</th><th>Status</th><th>Referensi</th><th>Diajukan</th></tr></thead><tbody><tr v-for="row in settlementRows" :key="row.settlement_id"><td>{{ row.business_name }}</td><td>{{ money(row.amount) }}</td><td>{{ row.status }}</td><td>{{ row.payment_reference || "-" }}</td><td>{{ formatDate(row.requested_at) }}</td></tr></tbody></table></div><div class="panel"><div class="heading"><h2>Rekonsiliasi saldo tenant</h2><button class="button secondary" @click="load">Muat ulang</button></div><div class="table-wrap"><table><thead><tr><th>Exhibitor</th><th>Total kredit</th><th>Pending</th><th>Confirmed</th><th>Saldo wallet</th><th>Status</th></tr></thead><tbody><tr v-for="row in reconciliation" :key="row.exhibitor_id"><td>{{ row.business_name }}</td><td>{{ money(row.total_credits) }}</td><td>{{ money(row.pending_settlement) }}</td><td>{{ money(row.confirmed_settlement) }}</td><td>{{ money(row.wallet_balance) }}</td><td>{{ row.status }}</td></tr></tbody></table></div></div></div></div></section>
</template>

<script setup lang="ts">
import type { AdminSettlement, ParticipantVoucher, SettlementReconciliation, VoucherParticipant } from '~/composables/useVoucherWallet';
import { useVoucherWallet } from '~/composables/useVoucherWallet';
definePageMeta({ middleware: ['auth', 'admin'] });
const api = useVoucherWallet(); const vouchers = ref<ParticipantVoucher[]>([]); const participants = ref<VoucherParticipant[]>([]); const settlementRows = ref<AdminSettlement[]>([]); const reconciliation = ref<SettlementReconciliation[]>([]); const busy = ref(false); const error = ref(''); const success = ref('');
const createForm = reactive({ participantId: '', initialBalance: 0 }); const adjustForm = reactive({ id: '', amount: 0, reason: '' });
const money = (value: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(value || 0); const formatDate = (value: string) => new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium' }).format(new Date(value));
const run = async (task: () => Promise<void>) => { busy.value = true; error.value = ''; success.value = ''; try { await task(); } catch (cause) { error.value = cause instanceof Error ? cause.message : 'Operasi gagal.'; } finally { busy.value = false; } };
const load = () => run(async () => { const [voucherResponse, participantResponse, settlementResponse, reconciliationResponse] = await Promise.all([api.adminVouchers(), api.voucherParticipants(), api.settlements(), api.settlementReconciliation()]); vouchers.value = voucherResponse.data; participants.value = participantResponse.data; settlementRows.value = settlementResponse.data; reconciliation.value = reconciliationResponse.data; });
const createVoucher = () => run(async () => { await api.createVoucher(createForm.participantId, Number(createForm.initialBalance)); success.value = 'Voucher reward diterbitkan.'; createForm.participantId = ''; createForm.initialBalance = 0; await load(); });
const adjustVoucher = () => run(async () => { await api.adjustVoucher(adjustForm.id, Number(adjustForm.amount), adjustForm.reason); success.value = 'Saldo voucher disesuaikan.'; adjustForm.id = ''; adjustForm.amount = 0; adjustForm.reason = ''; await load(); });
const revoke = (id: string) => run(async () => { await api.revokeVoucher(id); success.value = 'Voucher dinonaktifkan.'; await load(); });
onMounted(() => { void load(); }); useSeoMeta({ title: 'Admin Voucher | Hari Santri 2026' });
</script>

<style scoped>
.admin-page{min-height:72vh;background:#f5f5ef;color:#17352c;padding:3rem max(1rem,calc((100vw - 1100px)/2))}.admin-inner{max-width:1100px;margin:auto}.eyebrow{color:#2d7258;font-size:.72rem;font-weight:800;letter-spacing:.12em}.intro{max-width:50rem;color:#596d61;line-height:1.7}.panel{background:#fff;border:1px solid #d9e0d8;padding:1.25rem;margin-top:1rem}.panel h2{font:1.4rem Georgia,serif}.form-grid{display:flex;flex-wrap:wrap;gap:1rem}.form-grid label{display:grid;gap:.4rem;flex:1;min-width:220px;font-weight:800;color:#365444}.form-grid .wide{flex-basis:100%}input,select{font:inherit;padding:.7rem;border:1px solid #bdcdbf;border-radius:6px;font-weight:400}.button{border:1px solid #b8c9bd;padding:.7rem 1rem;font-weight:800;background:#fff;cursor:pointer}.primary{background:#d26c3e;color:#fff;border-color:#d26c3e}.secondary{color:#275d46}.heading{display:flex;justify-content:space-between;align-items:center}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:.7rem;border-bottom:1px solid #edf1ed;white-space:nowrap}th{font-size:.7rem;letter-spacing:.1em;color:#6c7e72}.link-button{border:0;background:transparent;color:#a53e28;font-weight:800;cursor:pointer}.error,.success{margin-top:1rem;padding:1rem;border-block:1px solid #d9e0d8}.error{color:#9a3022}.success{color:#21623b}
</style>
